type FileType = {
  created: number
  expires_at?: number | null
  filename?: string | null
  id: string
  links?: {
    data: readonly Schema.Schema.Type<typeof FileLinkSchema>[]
    has_more: boolean
    object: 'list'
    url: string
  } | null
  object: 'file'
  purpose:
    | 'account_requirement'
    | 'additional_verification'
    | 'business_icon'
    | 'business_logo'
    | 'customer_signature'
    | 'dispute_evidence'
    | 'document_provider_identity_document'
    | 'finance_report_run'
    | 'financial_account_statement'
    | 'identity_document'
    | 'identity_document_downloadable'
    | 'issuing_regulatory_reporting'
    | 'pci_document'
    | 'platform_terms_of_service'
    | 'selfie'
    | 'sigma_scheduled_query'
    | 'tax_document_user_upload'
    | 'terminal_android_apk'
    | 'terminal_reader_splashscreen'
    | 'terminal_wifi_certificate'
    | 'terminal_wifi_private_key'
  size: number
  title?: string | null
  type?: string | null
  url?: string | null
}

export const FileSchema: Schema.Codec<FileType, unknown> = Schema.Struct({
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  expires_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: "The file expires and isn't available at this time in epoch seconds.",
    }),
  ),
  filename: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'The suitable name for saving the file to a filesystem.' }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  links: Schema.optionalKey(
    Schema.NullOr(
      Schema.Struct({
        data: Schema.Array(Schema.suspend(() => FileLinkSchema)).annotate({
          description: 'Details about each object.',
        }),
        has_more: Schema.Boolean.annotate({
          description:
            'True if this list has another page of items after this one that can be fetched.',
        }),
        object: Schema.Literal('list').annotate({
          description:
            "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
        }),
        url: Schema.String.check(
          Schema.isPattern(/^\/v1\/file_links/),
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ).annotate({ description: 'The URL where this list can be accessed.' }),
      }),
    ).annotate({
      description:
        'A list of [file links](https://docs.stripe.com/api#file_links) that point at this file.',
    }),
  ),
  object: Schema.Literal('file').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  purpose: Schema.Literals([
    'account_requirement',
    'additional_verification',
    'business_icon',
    'business_logo',
    'customer_signature',
    'dispute_evidence',
    'document_provider_identity_document',
    'finance_report_run',
    'financial_account_statement',
    'identity_document',
    'identity_document_downloadable',
    'issuing_regulatory_reporting',
    'pci_document',
    'platform_terms_of_service',
    'selfie',
    'sigma_scheduled_query',
    'tax_document_user_upload',
    'terminal_android_apk',
    'terminal_reader_splashscreen',
    'terminal_wifi_certificate',
    'terminal_wifi_private_key',
  ]).annotate({
    description:
      'The [purpose](https://docs.stripe.com/file-upload#uploading-a-file) of the uploaded file.',
  }),
  size: Schema.Number.check(Schema.isInt()).annotate({
    description: 'The size of the file object in bytes.',
  }),
  title: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'A suitable title for the document.' }),
  ),
  type: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'The returned file type (for example, `csv`, `pdf`, `jpg`, or `png`).',
    }),
  ),
  url: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'Use your live secret API key to download the file from this URL.' }),
  ),
}).annotate({
  description:
    "This object represents files hosted on Stripe's servers. You can upload\nfiles with the [create file](https://docs.stripe.com/api#create_file) request\n(for example, when uploading dispute evidence). Stripe also\ncreates files independently (for example, the results of a [Sigma scheduled\nquery](#scheduled_queries)).\n\nRelated guide: [File upload guide](https://docs.stripe.com/file-upload)",
})

export type File = Schema.Schema.Type<typeof FileSchema>

type FileLinkType = {
  created: number
  expired: boolean
  expires_at?: number | null
  file: string | Schema.Schema.Type<typeof FileSchema>
  id: string
  livemode: boolean
  metadata: { [key: string]: string }
  object: 'file_link'
  url?: string | null
}

export const FileLinkSchema: Schema.Codec<FileLinkType, unknown> = Schema.Struct({
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  expired: Schema.Boolean.annotate({ description: 'Returns if the link is already expired.' }),
  expires_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'Time that the link expires.',
    }),
  ),
  file: Schema.Union([
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
    Schema.suspend(() => FileSchema),
  ]).annotate({ description: 'The file object this link points to.' }),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  metadata: Schema.Record(
    Schema.String,
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 500, {
        expected: 'a string of at most 500 characters',
      }),
    ),
  ).annotate({
    description:
      'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
  }),
  object: Schema.Literal('file_link').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  url: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'The publicly accessible URL to download the file.' }),
  ),
}).annotate({
  description:
    'To share the contents of a `File` object with non-Stripe users, you can\ncreate a `FileLink`. `FileLink`s contain a URL that you can use to\nretrieve the contents of the file without authentication.',
})

export type FileLink = Schema.Schema.Type<typeof FileLinkSchema>

