export const PaymentMethodBoletoSchema = Schema.Struct({
  tax_id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Uniquely identifies the customer tax id (CNPJ or CPF)' }),
}).annotate({ description: '' })

export type PaymentMethodBoleto = Schema.Schema.Type<typeof PaymentMethodBoletoSchema>

export const PaymentMethodCardChecksSchema = Schema.Struct({
  address_line1_check: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'If a address line1 was provided, results of the check, one of `pass`, `fail`, `unavailable`, or `unchecked`.',
    }),
  ),
  address_postal_code_check: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'If a address postal code was provided, results of the check, one of `pass`, `fail`, `unavailable`, or `unchecked`.',
    }),
  ),
  cvc_check: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'If a CVC was provided, results of the check, one of `pass`, `fail`, `unavailable`, or `unchecked`.',
    }),
  ),
}).annotate({ description: '' })

export type PaymentMethodCardChecks = Schema.Schema.Type<typeof PaymentMethodCardChecksSchema>

export const PaymentMethodDetailsCardPresentOfflineSchema = Schema.Struct({
  stored_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'Time at which the payment was collected while offline',
    }),
  ),
  type: Schema.optionalKey(
    Schema.NullOr(Schema.Literal('deferred')).annotate({
      description:
        'The method used to process this payment method offline. Only deferred is allowed.',
    }),
  ),
}).annotate({ description: '' })

export type PaymentMethodDetailsCardPresentOffline = Schema.Schema.Type<
  typeof PaymentMethodDetailsCardPresentOfflineSchema
>

export const PaymentMethodDetailsCardPresentReceiptSchema = Schema.Struct({
  account_type: Schema.optionalKey(
    Schema.Literals(['checking', 'credit', 'prepaid', 'unknown']).annotate({
      description: 'The type of account being debited or credited',
    }),
  ),
  application_cryptogram: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The Application Cryptogram, a unique value generated by the card to authenticate the transaction with issuers.',
    }),
  ),
  application_preferred_name: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "The Application Identifier (AID) on the card used to determine which networks are eligible to process the transaction. Referenced from EMV tag 9F12, data encoded on the card's chip.",
    }),
  ),
  authorization_code: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'Identifier for this transaction.' }),
  ),
  authorization_response_code: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'EMV tag 8A. A code returned by the card issuer.' }),
  ),
  cardholder_verification_method: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'Describes the method used by the cardholder to verify ownership of the card. One of the following: `approval`, `failure`, `none`, `offline_pin`, `offline_pin_and_signature`, `online_pin`, or `signature`.',
    }),
  ),
  dedicated_file_name: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'Similar to the application_preferred_name, identifying the applications (AIDs) available on the card. Referenced from EMV tag 84.',
    }),
  ),
  terminal_verification_results: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'A 5-byte string that records the checks and validations that occur between the card and the terminal. These checks determine how the terminal processes the transaction and what risk tolerance is acceptable. Referenced from EMV Tag 95.',
    }),
  ),
  transaction_status_information: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'An indication of which steps were completed during the card read process. Referenced from EMV Tag 9B.',
    }),
  ),
}).annotate({ description: '' })

export type PaymentMethodDetailsCardPresentReceipt = Schema.Schema.Type<
  typeof PaymentMethodDetailsCardPresentReceiptSchema
>

