type AccountType = {
  business_profile?: Schema.Schema.Type<typeof AccountBusinessProfileSchema>
  business_type?: 'company' | 'government_entity' | 'individual' | 'non_profit'
  capabilities?: Schema.Schema.Type<typeof AccountCapabilitiesSchema>
  charges_enabled?: boolean
  company?: Schema.Schema.Type<typeof LegalEntityCompanySchema>
  controller?: Schema.Schema.Type<typeof AccountUnificationAccountControllerSchema>
  country?: string
  created?: number
  default_currency?: string
  details_submitted?: boolean
  email?: string | null
  external_accounts?: {
    data: readonly (
      | Schema.Schema.Type<typeof BankAccountSchema>
      | Schema.Schema.Type<typeof CardSchema>
    )[]
    has_more: boolean
    object: 'list'
    url: string
  }
  future_requirements?: Schema.Schema.Type<typeof AccountFutureRequirementsSchema>
  groups?: Schema.Schema.Type<typeof AccountGroupMembershipSchema>
  id: string
  individual?: Schema.Schema.Type<typeof PersonSchema>
  metadata?: { [key: string]: string }
  object: 'account'
  payouts_enabled?: boolean
  requirements?: Schema.Schema.Type<typeof AccountRequirementsSchema>
  settings?: Schema.Schema.Type<typeof AccountSettingsSchema>
  tos_acceptance?: Schema.Schema.Type<typeof AccountTosAcceptanceSchema>
  type?: 'custom' | 'express' | 'none' | 'standard'
}

export const AccountSchema: Schema.Codec<AccountType, unknown> = Schema.Struct({
  business_profile: Schema.optionalKey(
    Schema.NullOr(Schema.Union([AccountBusinessProfileSchema])).annotate({
      description: 'Business information about the account.',
    }),
  ),
  business_type: Schema.optionalKey(
    Schema.NullOr(
      Schema.Literals(['company', 'government_entity', 'individual', 'non_profit']),
    ).annotate({ description: 'The business type.' }),
  ),
  capabilities: Schema.optionalKey(AccountCapabilitiesSchema),
  charges_enabled: Schema.optionalKey(
    Schema.Boolean.annotate({ description: 'Whether the account can process charges.' }),
  ),
  company: Schema.optionalKey(LegalEntityCompanySchema),
  controller: Schema.optionalKey(AccountUnificationAccountControllerSchema),
  country: Schema.optionalKey(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: "The account's country." }),
  ),
  created: Schema.optionalKey(
    Schema.Number.check(Schema.isInt()).annotate({
      description:
        'Time at which the account was connected. Measured in seconds since the Unix epoch.',
    }),
  ),
  default_currency: Schema.optionalKey(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({
      description:
        "Three-letter ISO currency code representing the default currency for the account. This must be a currency that [Stripe supports in the account's country](https://stripe.com/docs/payouts).",
    }),
  ),
  details_submitted: Schema.optionalKey(
    Schema.Boolean.annotate({
      description:
        'Whether account details have been submitted. Accounts with Stripe Dashboard access, which includes Standard accounts, cannot receive payouts before this is true. Accounts where this is false should be directed to [an onboarding flow](/connect/onboarding) to finish submitting account details.',
    }),
  ),
  email: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "An email address associated with the account. It's not used for authentication and Stripe doesn't market to this field without explicit approval from the platform.",
    }),
  ),
  external_accounts: Schema.optionalKey(
    Schema.Struct({
      data: Schema.Array(
        Schema.Union([Schema.suspend(() => BankAccountSchema), Schema.suspend(() => CardSchema)]),
      ).annotate({
        description:
          'The list contains all external accounts that have been attached to the Stripe account. These may be bank accounts or cards.',
      }),
      has_more: Schema.Boolean.annotate({
        description:
          'True if this list has another page of items after this one that can be fetched.',
      }),
      object: Schema.Literal('list').annotate({
        description:
          "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
      }),
      url: Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ).annotate({ description: 'The URL where this list can be accessed.' }),
    }).annotate({
      description:
        'External accounts (bank accounts and debit cards) currently attached to this account. External accounts are only returned for requests where `controller[is_controller]` is true.',
    }),
  ),
  future_requirements: Schema.optionalKey(AccountFutureRequirementsSchema),
  groups: Schema.optionalKey(
    Schema.NullOr(Schema.Union([AccountGroupMembershipSchema])).annotate({
      description: 'The groups associated with the account.',
    }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  individual: Schema.optionalKey(PersonSchema),
  metadata: Schema.optionalKey(
    Schema.Record(
      Schema.String,
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 500, {
          expected: 'a string of at most 500 characters',
        }),
      ),
    ).annotate({
      description:
        'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
    }),
  ),
  object: Schema.Literal('account').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  payouts_enabled: Schema.optionalKey(
    Schema.Boolean.annotate({ description: 'Whether the funds in this account can be paid out.' }),
  ),
  requirements: Schema.optionalKey(AccountRequirementsSchema),
  settings: Schema.optionalKey(
    Schema.NullOr(Schema.Union([Schema.suspend(() => AccountSettingsSchema)])).annotate({
      description: 'Options for customizing how the account functions within Stripe.',
    }),
  ),
  tos_acceptance: Schema.optionalKey(AccountTosAcceptanceSchema),
  type: Schema.optionalKey(
    Schema.Literals(['custom', 'express', 'none', 'standard']).annotate({
      description: 'The Stripe account type. Can be `standard`, `express`, `custom`, or `none`.',
    }),
  ),
}).annotate({
  description:
    'For new integrations, we recommend using the [Accounts v2 API](/api/v2/core/accounts), in place of /v1/accounts and /v1/customers to represent a user.\n\nThis is an object representing a Stripe account. You can retrieve it to see\nproperties on the account like its current requirements or if the account is\nenabled to make live charges or receive payouts.\n\nFor accounts where [controller.requirement_collection](/api/accounts/object#account_object-controller-requirement_collection)\nis `application`, which includes Custom accounts, the properties below are always\nreturned.\n\nFor accounts where [controller.requirement_collection](/api/accounts/object#account_object-controller-requirement_collection)\nis `stripe`, which includes Standard and Express accounts, some properties are only returned\nuntil you create an [Account Link](/api/account_links) or [Account Session](/api/account_sessions)\nto start Connect Onboarding. Learn about the [differences between accounts](/connect/accounts).',
})

