type DiscountType = {
  checkout_session?: string | null
  customer?:
    | string
    | Schema.Schema.Type<typeof CustomerSchema>
    | Schema.Schema.Type<typeof DeletedCustomerSchema>
  customer_account?: string | null
  end?: number | null
  id: string
  invoice?: string | null
  invoice_item?: string | null
  object: 'discount'
  promotion_code?: string | Schema.Schema.Type<typeof PromotionCodeSchema>
  source: Schema.Schema.Type<typeof DiscountSourceSchema>
  start: number
  subscription?: string | null
  subscription_item?: string | null
}

export const DiscountSchema: Schema.Codec<DiscountType, unknown> = Schema.Struct({
  checkout_session: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The Checkout session that this coupon is applied to, if it is applied to a particular session in payment mode. Not present for subscription mode.',
    }),
  ),
  customer: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => CustomerSchema),
        DeletedCustomerSchema,
      ]),
    ).annotate({ description: 'The ID of the customer associated with this discount.' }),
  ),
  customer_account: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'The ID of the account representing the customer associated with this discount.',
    }),
  ),
  end: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'If the coupon has a duration of `repeating`, the date that this discount will end. If the coupon has a duration of `once` or `forever`, this attribute will be null.',
    }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      "The ID of the discount object. Discounts can't be fetched by ID. Use `expand[]=discounts` in API calls to expand discount IDs in an array.",
  }),
  invoice: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "The invoice that the discount's coupon was applied to, if it was applied directly to a particular invoice.",
    }),
  ),
  invoice_item: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "The invoice item `id` (or invoice line item `id` for invoice line items of type='subscription') that the discount's coupon was applied to, if it was applied directly to a particular invoice item or invoice line item.",
    }),
  ),
  object: Schema.Literal('discount').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  promotion_code: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => PromotionCodeSchema),
      ]),
    ).annotate({ description: 'The promotion code applied to create this discount.' }),
  ),
  source: DiscountSourceSchema,
  start: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Date that the coupon was applied.',
  }),
  subscription: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The subscription that this coupon is applied to, if it is applied to a particular subscription.',
    }),
  ),
  subscription_item: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The subscription item that this coupon is applied to, if it is applied to a particular subscription item.',
    }),
  ),
}).annotate({
  description:
    'A discount represents the actual application of a [coupon](https://docs.stripe.com/api#coupons) or [promotion code](https://docs.stripe.com/api#promotion_codes).\nIt contains information about when the discount began, when it will end, and what it is applied to.\n\nRelated guide: [Applying discounts to subscriptions](https://docs.stripe.com/billing/subscriptions/discounts)',
})

