type PromotionCodeType = {
  active: boolean
  code: string
  created: number
  customer?:
    | string
    | Schema.Schema.Type<typeof CustomerSchema>
    | Schema.Schema.Type<typeof DeletedCustomerSchema>
  customer_account?: string | null
  expires_at?: number | null
  id: string
  livemode: boolean
  max_redemptions?: number | null
  metadata?: { [key: string]: string } | null
  object: 'promotion_code'
  promotion: Schema.Schema.Type<typeof PromotionCodesResourcePromotionSchema>
  restrictions: Schema.Schema.Type<typeof PromotionCodesResourceRestrictionsSchema>
  times_redeemed: number
}

export const PromotionCodeSchema: Schema.Codec<PromotionCodeType, unknown> = Schema.Struct({
  active: Schema.Boolean.annotate({
    description:
      'Whether the promotion code is currently active. A promotion code is only active if the coupon is also valid.',
  }),
  code: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'The customer-facing code. Regardless of case, this code must be unique across all active promotion codes for each customer. Valid characters are lower case letters (a-z), upper case letters (A-Z), digits (0-9), and dashes (-).',
  }),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  customer: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => CustomerSchema),
        DeletedCustomerSchema,
      ]),
    ).annotate({ description: 'The customer who can use this promotion code.' }),
  ),
  customer_account: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'The account representing the customer who can use this promotion code.',
    }),
  ),
  expires_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'Date at which the promotion code can no longer be redeemed.',
    }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  max_redemptions: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'Maximum number of times this promotion code can be redeemed.',
    }),
  ),
  metadata: Schema.optionalKey(
    Schema.NullOr(
      Schema.Record(
        Schema.String,
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 500, {
            expected: 'a string of at most 500 characters',
          }),
        ),
      ),
    ).annotate({
      description:
        'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
    }),
  ),
  object: Schema.Literal('promotion_code').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  promotion: PromotionCodesResourcePromotionSchema,
  restrictions: PromotionCodesResourceRestrictionsSchema,
  times_redeemed: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Number of times this promotion code has been used.',
  }),
}).annotate({
  description:
    'A Promotion Code represents a customer-redeemable code for an underlying promotion.\nYou can create multiple codes for a single promotion.\n\nIf you enable promotion codes in your [customer portal configuration](https://docs.stripe.com/customer-management/configure-portal), then customers can redeem a code themselves when updating a subscription in the portal.\nCustomers can also view the currently active promotion codes and coupons on each of their subscriptions in the portal.',
})

export type PromotionCode = Schema.Schema.Type<typeof PromotionCodeSchema>

