type PaymentMethodCardType = {
  brand: string
  checks?: Schema.Schema.Type<typeof PaymentMethodCardChecksSchema>
  country?: string | null
  display_brand?: string | null
  exp_month: number
  exp_year: number
  fingerprint?: string | null
  funding: string
  generated_from?: Schema.Schema.Type<typeof PaymentMethodCardGeneratedCardSchema>
  last4: string
  networks?: Schema.Schema.Type<typeof NetworksSchema>
  regulated_status?: 'regulated' | 'unregulated'
  three_d_secure_usage?: Schema.Schema.Type<typeof ThreeDSecureUsageSchema>
  wallet?: Schema.Schema.Type<typeof PaymentMethodCardWalletSchema>
}

export const PaymentMethodCardSchema: Schema.Codec<PaymentMethodCardType, unknown> = Schema.Struct({
  brand: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'Card brand. Can be `amex`, `cartes_bancaires`, `diners`, `discover`, `eftpos_au`, `jcb`, `link`, `mastercard`, `unionpay`, `visa` or `unknown`.',
  }),
  checks: Schema.optionalKey(
    Schema.NullOr(Schema.Union([PaymentMethodCardChecksSchema])).annotate({
      description: 'Checks on Card address and CVC if provided.',
    }),
  ),
  country: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "Two-letter ISO code representing the country of the card. You could use this attribute to get a sense of the international breakdown of cards you've collected.",
    }),
  ),
  display_brand: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "The brand to use when displaying the card, this accounts for customer's brand choice on dual-branded cards. Can be `american_express`, `cartes_bancaires`, `diners_club`, `discover`, `eftpos_australia`, `interac`, `jcb`, `mastercard`, `union_pay`, `visa`, or `other` and may contain more values in the future.",
    }),
  ),
  exp_month: Schema.Number.check(Schema.isInt()).annotate({
    description: "Two-digit number representing the card's expiration month.",
  }),
  exp_year: Schema.Number.check(Schema.isInt()).annotate({
    description: "Four-digit number representing the card's expiration year.",
  }),
  fingerprint: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'Uniquely identifies this particular card number. You can use this attribute to check whether two customers who’ve signed up with you are using the same card number, for example. For payment methods that tokenize card information (Apple Pay, Google Pay), the tokenized number might be provided instead of the underlying card number.\n\n*As of May 1, 2021, card fingerprint in India for Connect changed to allow two fingerprints for the same card---one for India and one for the rest of the world.*',
    }),
  ),
  funding: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description: 'Card funding type. Can be `credit`, `debit`, `prepaid`, or `unknown`.',
  }),
  generated_from: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([Schema.suspend(() => PaymentMethodCardGeneratedCardSchema)]),
    ).annotate({ description: 'Details of the original PaymentMethod that created this object.' }),
  ),
  last4: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'The last four digits of the card.' }),
  networks: Schema.optionalKey(
    Schema.NullOr(Schema.Union([NetworksSchema])).annotate({
      description:
        'Contains information about card networks that can be used to process the payment.',
    }),
  ),
  regulated_status: Schema.optionalKey(
    Schema.NullOr(Schema.Literals(['regulated', 'unregulated'])).annotate({
      description: 'Status of a card based on the card issuer.',
    }),
  ),
  three_d_secure_usage: Schema.optionalKey(
    Schema.NullOr(Schema.Union([ThreeDSecureUsageSchema])).annotate({
      description: 'Contains details on how this Card may be used for 3D Secure authentication.',
    }),
  ),
  wallet: Schema.optionalKey(
    Schema.NullOr(Schema.Union([PaymentMethodCardWalletSchema])).annotate({
      description:
        'If this Card is part of a card wallet, this contains the details of the card wallet.',
    }),
  ),
}).annotate({ description: '' })

