type ReviewType = {
  billing_zip?: string | null
  charge?: string | Schema.Schema.Type<typeof ChargeSchema>
  closed_reason?:
    | 'acknowledged'
    | 'approved'
    | 'canceled'
    | 'disputed'
    | 'payment_never_settled'
    | 'redacted'
    | 'refunded'
    | 'refunded_as_fraud'
  created: number
  id: string
  ip_address?: string | null
  ip_address_location?: Schema.Schema.Type<typeof RadarReviewResourceLocationSchema>
  livemode: boolean
  object: 'review'
  open: boolean
  opened_reason: 'manual' | 'rule'
  payment_intent?: string | Schema.Schema.Type<typeof PaymentIntentSchema>
  reason: string
  session?: Schema.Schema.Type<typeof RadarReviewResourceSessionSchema>
}

export const ReviewSchema: Schema.Codec<ReviewType, unknown> = Schema.Struct({
  billing_zip: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'The ZIP or postal code of the card used, if applicable.' }),
  ),
  charge: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => ChargeSchema),
      ]),
    ).annotate({ description: 'The charge associated with this review.' }),
  ),
  closed_reason: Schema.optionalKey(
    Schema.NullOr(
      Schema.Literals([
        'acknowledged',
        'approved',
        'canceled',
        'disputed',
        'payment_never_settled',
        'redacted',
        'refunded',
        'refunded_as_fraud',
      ]),
    ).annotate({
      description:
        'The reason the review was closed, or null if it has not yet been closed. One of `approved`, `refunded`, `refunded_as_fraud`, `disputed`, `redacted`, `canceled`, `payment_never_settled`, or `acknowledged`.',
    }),
  ),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  ip_address: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'The IP address where the payment originated.' }),
  ),
  ip_address_location: Schema.optionalKey(
    Schema.NullOr(Schema.Union([RadarReviewResourceLocationSchema])).annotate({
      description:
        'Information related to the location of the payment. Note that this information is an approximation and attempts to locate the nearest population center - it should not be used to determine a specific address.',
    }),
  ),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  object: Schema.Literal('review').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  open: Schema.Boolean.annotate({ description: 'If `true`, the review needs action.' }),
  opened_reason: Schema.Literals(['manual', 'rule']).annotate({
    description: 'The reason the review was opened. One of `rule` or `manual`.',
  }),
  payment_intent: Schema.optionalKey(
    Schema.Union([
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
      Schema.suspend(() => PaymentIntentSchema),
    ]).annotate({
      description: 'The PaymentIntent ID associated with this review, if one exists.',
    }),
  ),
  reason: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'The reason the review is currently open or closed. One of `rule`, `manual`, `approved`, `refunded`, `refunded_as_fraud`, `disputed`, `redacted`, `canceled`, `payment_never_settled`, or `acknowledged`.',
  }),
  session: Schema.optionalKey(
    Schema.NullOr(Schema.Union([RadarReviewResourceSessionSchema])).annotate({
      description:
        'Information related to the browsing session of the user who initiated the payment.',
    }),
  ),
}).annotate({
  description:
    'Reviews can be used to supplement automated fraud detection with human expertise.\n\nLearn more about [Radar](/radar) and reviewing payments\n[here](https://docs.stripe.com/radar/reviews).',
})

