type CustomerBalanceTransactionType = {
  amount: number
  checkout_session?: string | Schema.Schema.Type<typeof CheckoutSessionSchema>
  created: number
  credit_note?: string | Schema.Schema.Type<typeof CreditNoteSchema>
  currency: string
  customer: string | Schema.Schema.Type<typeof CustomerSchema>
  customer_account?: string | null
  description?: string | null
  ending_balance: number
  id: string
  invoice?: string | Schema.Schema.Type<typeof InvoiceSchema>
  livemode: boolean
  metadata?: { [key: string]: string } | null
  object: 'customer_balance_transaction'
  type:
    | 'adjustment'
    | 'applied_to_invoice'
    | 'checkout_session_subscription_payment'
    | 'checkout_session_subscription_payment_canceled'
    | 'credit_note'
    | 'initial'
    | 'invoice_overpaid'
    | 'invoice_too_large'
    | 'invoice_too_small'
    | 'migration'
    | 'unapplied_from_invoice'
    | 'unspent_receiver_credit'
}

export const CustomerBalanceTransactionSchema: Schema.Codec<
  CustomerBalanceTransactionType,
  unknown
> = Schema.Struct({
  amount: Schema.Number.check(Schema.isInt()).annotate({
    description:
      "The amount of the transaction. A negative value is a credit for the customer's balance, and a positive value is a debit to the customer's `balance`.",
  }),
  checkout_session: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        CheckoutSessionSchema,
      ]),
    ).annotate({
      description: 'The ID of the checkout session (if any) that created the transaction.',
    }),
  ),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  credit_note: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => CreditNoteSchema),
      ]),
    ).annotate({ description: 'The ID of the credit note (if any) related to the transaction.' }),
  ),
  currency: Schema.String.annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
  customer: Schema.Union([
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
    CustomerSchema,
  ]).annotate({ description: 'The ID of the customer the transaction belongs to.' }),
  customer_account: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'The ID of an Account representing a customer that the transaction belongs to.',
    }),
  ),
  description: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'An arbitrary string attached to the object. Often useful for displaying to users.',
    }),
  ),
  ending_balance: Schema.Number.check(Schema.isInt()).annotate({
    description:
      "The customer's `balance` after the transaction was applied. A negative value decreases the amount due on the customer's next invoice. A positive value increases the amount due on the customer's next invoice.",
  }),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  invoice: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        InvoiceSchema,
      ]),
    ).annotate({ description: 'The ID of the invoice (if any) related to the transaction.' }),
  ),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  metadata: Schema.optionalKey(
    Schema.NullOr(
      Schema.Record(
        Schema.String,
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 500, {
            expected: 'a string of at most 500 characters',
          }),
        ),
      ),
    ).annotate({
      description:
        'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
    }),
  ),
  object: Schema.Literal('customer_balance_transaction').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  type: Schema.Literals([
    'adjustment',
    'applied_to_invoice',
    'checkout_session_subscription_payment',
    'checkout_session_subscription_payment_canceled',
    'credit_note',
    'initial',
    'invoice_overpaid',
    'invoice_too_large',
    'invoice_too_small',
    'migration',
    'unapplied_from_invoice',
    'unspent_receiver_credit',
  ]).annotate({
    description:
      'Transaction type: `adjustment`, `applied_to_invoice`, `credit_note`, `initial`, `invoice_overpaid`, `invoice_too_large`, `invoice_too_small`, `unspent_receiver_credit`, `unapplied_from_invoice`, `checkout_session_subscription_payment`, or `checkout_session_subscription_payment_canceled`. See the [Customer Balance page](https://docs.stripe.com/billing/customer/balance#types) to learn more about transaction types.',
  }),
}).annotate({
  description:
    "Each customer has a [Balance](https://docs.stripe.com/api/customers/object#customer_object-balance) value,\nwhich denotes a debit or credit that's automatically applied to their next invoice upon finalization.\nYou may modify the value directly by using the [update customer API](https://docs.stripe.com/api/customers/update),\nor by creating a Customer Balance Transaction, which increments or decrements the customer's `balance` by the specified `amount`.\n\nRelated guide: [Customer balance](https://docs.stripe.com/billing/customer/balance)",
})

