type QuoteType = {
  amount_subtotal: number
  amount_total: number
  application?:
    | string
    | Schema.Schema.Type<typeof ApplicationSchema>
    | Schema.Schema.Type<typeof DeletedApplicationSchema>
  application_fee_amount?: number | null
  application_fee_percent?: number | null
  automatic_tax: Schema.Schema.Type<typeof QuotesResourceAutomaticTaxSchema>
  collection_method: 'charge_automatically' | 'send_invoice'
  computed: Schema.Schema.Type<typeof QuotesResourceComputedSchema>
  created: number
  currency?: string | null
  customer?:
    | string
    | Schema.Schema.Type<typeof CustomerSchema>
    | Schema.Schema.Type<typeof DeletedCustomerSchema>
  customer_account?: string | null
  default_tax_rates?: readonly (string | Schema.Schema.Type<typeof TaxRateSchema>)[]
  description?: string | null
  discounts: readonly (string | Schema.Schema.Type<typeof DiscountSchema>)[]
  expires_at: number
  footer?: string | null
  from_quote?: Schema.Schema.Type<typeof QuotesResourceFromQuoteSchema>
  header?: string | null
  id: string
  invoice?:
    | string
    | Schema.Schema.Type<typeof InvoiceSchema>
    | Schema.Schema.Type<typeof DeletedInvoiceSchema>
  invoice_settings: Schema.Schema.Type<typeof InvoiceSettingQuoteSettingSchema>
  line_items?: {
    data: readonly Schema.Schema.Type<typeof ItemSchema>[]
    has_more: boolean
    object: 'list'
    url: string
  }
  livemode: boolean
  metadata: { [key: string]: string }
  number?: string | null
  object: 'quote'
  on_behalf_of?: string | Schema.Schema.Type<typeof AccountSchema>
  status: 'accepted' | 'canceled' | 'draft' | 'open'
  status_transitions: Schema.Schema.Type<typeof QuotesResourceStatusTransitionsSchema>
  subscription?: string | Schema.Schema.Type<typeof SubscriptionSchema>
  subscription_data: Schema.Schema.Type<typeof QuotesResourceSubscriptionDataSubscriptionDataSchema>
  subscription_schedule?: string | Schema.Schema.Type<typeof SubscriptionScheduleSchema>
  test_clock?: string | Schema.Schema.Type<typeof TestHelpersTestClockSchema>
  total_details: Schema.Schema.Type<typeof QuotesResourceTotalDetailsSchema>
  transfer_data?: Schema.Schema.Type<typeof QuotesResourceTransferDataSchema>
}

