export const TaxCalculationSchema = Schema.Struct({
  amount_total: Schema.Number.check(Schema.isInt()).annotate({
    description:
      'Total amount after taxes in the [smallest currency unit](https://docs.stripe.com/currencies#minor-units).',
  }),
  currency: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
  customer: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The ID of an existing [Customer](https://docs.stripe.com/api/customers/object) used for the resource.',
    }),
  ),
  customer_details: TaxProductResourceCustomerDetailsSchema,
  expires_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'Timestamp of date at which the tax calculation will expire.',
    }),
  ),
  id: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'Unique identifier for the calculation.' }),
  ),
  line_items: Schema.optionalKey(
    Schema.NullOr(
      Schema.Struct({
        data: Schema.Array(TaxCalculationLineItemSchema).annotate({
          description: 'Details about each object.',
        }),
        has_more: Schema.Boolean.annotate({
          description:
            'True if this list has another page of items after this one that can be fetched.',
        }),
        object: Schema.Literal('list').annotate({
          description:
            "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
        }),
        url: Schema.String.check(
          Schema.isPattern(/^\/v1\/tax\/calculations\/[^\/]+\/line_items/),
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ).annotate({ description: 'The URL where this list can be accessed.' }),
      }),
    ).annotate({ description: 'The list of items the customer is purchasing.' }),
  ),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  object: Schema.Literal('tax.calculation').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  ship_from_details: Schema.optionalKey(
    Schema.NullOr(Schema.Union([TaxProductResourceShipFromDetailsSchema])).annotate({
      description: 'The details of the ship from location, such as the address.',
    }),
  ),
  shipping_cost: Schema.optionalKey(
    Schema.NullOr(Schema.Union([TaxProductResourceTaxCalculationShippingCostSchema])).annotate({
      description: 'The shipping cost details for the calculation.',
    }),
  ),
  tax_amount_exclusive: Schema.Number.check(Schema.isInt()).annotate({
    description: 'The amount of tax to be collected on top of the line item prices.',
  }),
  tax_amount_inclusive: Schema.Number.check(Schema.isInt()).annotate({
    description: 'The amount of tax already included in the line item prices.',
  }),
  tax_breakdown: Schema.Array(TaxProductResourceTaxBreakdownSchema).annotate({
    description: 'Breakdown of individual tax amounts that add up to the total.',
  }),
  tax_date: Schema.Number.check(Schema.isInt()).annotate({
    description:
      "The calculation uses the tax rules and rates that are in effect at this timestamp. You can use a date up to 31 days in the past or up to 31 days in the future. If you use a future date, Stripe doesn't guarantee that the expected tax rules and rate being used match the actual rules and rate that will be in effect on that date. We deploy tax changes before their effective date, but not within a fixed window.",
  }),
}).annotate({
  description:
    'A Tax Calculation allows you to calculate the tax to collect from your customer.\n\nRelated guide: [Calculate tax in your custom payment flow](https://docs.stripe.com/tax/custom)',
})

