export const TaxTransactionSchema = Schema.Struct({
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  currency: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
  customer: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The ID of an existing [Customer](https://docs.stripe.com/api/customers/object) used for the resource.',
    }),
  ),
  customer_details: TaxProductResourceCustomerDetailsSchema,
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the transaction.' }),
  line_items: Schema.optionalKey(
    Schema.NullOr(
      Schema.Struct({
        data: Schema.Array(TaxTransactionLineItemSchema).annotate({
          description: 'Details about each object.',
        }),
        has_more: Schema.Boolean.annotate({
          description:
            'True if this list has another page of items after this one that can be fetched.',
        }),
        object: Schema.Literal('list').annotate({
          description:
            "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
        }),
        url: Schema.String.check(
          Schema.isPattern(/^\/v1\/tax\/transactions\/[^\/]+\/line_items/),
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ).annotate({ description: 'The URL where this list can be accessed.' }),
      }),
    ).annotate({ description: 'The tax collected or refunded, by line item.' }),
  ),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  metadata: Schema.optionalKey(
    Schema.NullOr(
      Schema.Record(
        Schema.String,
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 500, {
            expected: 'a string of at most 500 characters',
          }),
        ),
      ),
    ).annotate({
      description:
        'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
    }),
  ),
  object: Schema.Literal('tax.transaction').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  posted_at: Schema.Number.check(Schema.isInt()).annotate({
    description: 'The Unix timestamp representing when the tax liability is assumed or reduced.',
  }),
  reference: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: "A custom unique identifier, such as 'myOrder_123'." }),
  reversal: Schema.optionalKey(
    Schema.NullOr(Schema.Union([TaxProductResourceTaxTransactionResourceReversalSchema])).annotate({
      description: 'If `type=reversal`, contains information about what was reversed.',
    }),
  ),
  ship_from_details: Schema.optionalKey(
    Schema.NullOr(Schema.Union([TaxProductResourceShipFromDetailsSchema])).annotate({
      description: 'The details of the ship from location, such as the address.',
    }),
  ),
  shipping_cost: Schema.optionalKey(
    Schema.NullOr(Schema.Union([TaxProductResourceTaxTransactionShippingCostSchema])).annotate({
      description: 'The shipping cost details for the transaction.',
    }),
  ),
  tax_date: Schema.Number.check(Schema.isInt()).annotate({
    description:
      "The calculation uses the tax rules and rates that are in effect at this timestamp. You can use a date up to 31 days in the past or up to 31 days in the future. If you use a future date, Stripe doesn't guarantee that the expected tax rules and rate being used match the actual rules and rate that will be in effect on that date. We deploy tax changes before their effective date, but not within a fixed window.",
  }),
  type: Schema.Literals(['reversal', 'transaction']).annotate({
    description: 'If `reversal`, this transaction reverses an earlier transaction.',
  }),
}).annotate({
  description:
    'A Tax Transaction records the tax collected from or refunded to your customer.\n\nRelated guide: [Calculate tax in your custom payment flow](https://docs.stripe.com/tax/custom#tax-transaction)',
})

