export const ThreeDSecureAuthenticationSchema = Schema.Struct({
  acquirer_details: Schema.optionalKey(ThreeDSecureStandaloneResourceAcquirerDetailsSchema),
  amount: Schema.optionalKey(
    Schema.Number.check(Schema.isInt()).annotate({
      description: 'The amount for this 3DS Authentication.',
    }),
  ),
  challenge_url: Schema.optionalKey(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({
      description:
        'The URL for presenting a challenge to your cardholder, present if status is requires_challenge.',
    }),
  ),
  channel: ThreeDSecureStandaloneResourceChannelSchema,
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  currency: Schema.optionalKey(
    Schema.String.annotate({
      description:
        'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
    }),
  ),
  directory_server: Schema.Literals([
    'american_express',
    'cartes_bancaires',
    'discover',
    'mastercard',
    'visa',
  ]).annotate({
    description: 'The 3DS directory server with which this 3DS Authentication was processed.',
  }),
  fingerprinting_url: Schema.optionalKey(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({
      description:
        'The URL for performing issuer fingerprinting, present if fingerprinting is supported for the given payment method.',
    }),
  ),
  flow_preference: Schema.optionalKey(ThreeDSecureStandaloneResourceFlowPreferenceSchema),
  future_usage: Schema.optionalKey(ThreeDSecureStandaloneResourceFutureUsageSchema),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  message_category: Schema.Literals([
    'non_payment_authentication',
    'payment_authentication',
  ]).annotate({
    description:
      'Indicates whether this 3DS Authentication is being performed for a payment or non-payment use case.',
  }),
  metadata: Schema.optionalKey(
    Schema.NullOr(
      Schema.Record(
        Schema.String,
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 500, {
            expected: 'a string of at most 500 characters',
          }),
        ),
      ),
    ).annotate({
      description:
        'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
    }),
  ),
  object: Schema.Literal('three_d_secure.authentication').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  outcome: Schema.optionalKey(
    Schema.Literals([
      'abandoned',
      'attempt_acknowledged',
      'authenticated',
      'canceled',
      'denied',
      'informational',
      'internal_error',
      'not_supported',
      'not_triggered',
      'processing_error',
      'rejected',
    ]).annotate({ description: 'The outcome of this 3DS Authentication.' }),
  ),
  outcome_details: Schema.optionalKey(ThreeDSecureStandaloneResourceOutcomeDetailsSchema),
  payment_method: Schema.Union([
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
    PaymentMethodSchema,
  ]).annotate({
    description:
      'ID of the payment method (a PaymentMethod object) to attach to this 3DS Authentication.',
  }),
  reason: Schema.optionalKey(
    Schema.Literals([
      'cardholder_authentication',
      'issuer_requested',
      'liability_shift',
      'processing_costs',
      'regulatory_compliance',
    ]).annotate({ description: 'The reason for invoking this 3DS Authentication.' }),
  ),
  shipping_address: Schema.optionalKey(ThreeDSecureStandaloneResourceShippingAddressSchema),
  status: Schema.Literals([
    'canceled',
    'error',
    'failed',
    'requires_challenge',
    'requires_submission',
    'succeeded',
  ]).annotate({ description: 'Status of this Authentication.' }),
}).annotate({
  description:
    'The Standalone 3DS API allows you to run EMV 3D Secure (3DS) authentication using Stripe while authorizing the payment with any PSP.\n\nRelated guide: [Standalone 3DS](/payments/3d-secure/standalone-3d-secure)',
})

