type TreasuryCreditReversalType = {
  amount: number
  created: number
  currency: string
  financial_account: string
  hosted_regulatory_receipt_url?: string | null
  id: string
  livemode: boolean
  metadata: { [key: string]: string }
  network: 'ach' | 'stripe'
  object: 'treasury.credit_reversal'
  received_credit: string
  status: 'canceled' | 'posted' | 'processing'
  status_transitions: Schema.Schema.Type<
    typeof TreasuryReceivedCreditsResourceStatusTransitionsSchema
  >
  transaction?: string | Schema.Schema.Type<typeof TreasuryTransactionSchema>
}

export const TreasuryCreditReversalSchema: Schema.Codec<TreasuryCreditReversalType, unknown> =
  Schema.Struct({
    amount: Schema.Number.check(Schema.isInt()).annotate({
      description: 'Amount (in cents) transferred.',
    }),
    created: Schema.Number.check(Schema.isInt()).annotate({
      description:
        'Time at which the object was created. Measured in seconds since the Unix epoch.',
    }),
    currency: Schema.String.annotate({
      description:
        'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
    }),
    financial_account: Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: 'The FinancialAccount to reverse funds from.' }),
    hosted_regulatory_receipt_url: Schema.optionalKey(
      Schema.NullOr(
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
      ).annotate({
        description:
          "A [hosted transaction receipt](https://docs.stripe.com/treasury/moving-money/regulatory-receipts) URL that is provided when money movement is considered regulated under Stripe's money transmission licenses.",
      }),
    ),
    id: Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: 'Unique identifier for the object.' }),
    livemode: Schema.Boolean.annotate({
      description:
        'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
    }),
    metadata: Schema.Record(
      Schema.String,
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 500, {
          expected: 'a string of at most 500 characters',
        }),
      ),
    ).annotate({
      description:
        'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
    }),
    network: Schema.Literals(['ach', 'stripe']).annotate({
      description: 'The rails used to reverse the funds.',
    }),
    object: Schema.Literal('treasury.credit_reversal').annotate({
      description:
        "String representing the object's type. Objects of the same type share the same value.",
    }),
    received_credit: Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: 'The ReceivedCredit being reversed.' }),
    status: Schema.Literals(['canceled', 'posted', 'processing']).annotate({
      description: 'Status of the CreditReversal',
    }),
    status_transitions: TreasuryReceivedCreditsResourceStatusTransitionsSchema,
    transaction: Schema.optionalKey(
      Schema.NullOr(
        Schema.Union([
          Schema.String.check(
            Schema.makeFilter((input) => [...input].length <= 5000, {
              expected: 'a string of at most 5000 characters',
            }),
          ),
          Schema.suspend(() => TreasuryTransactionSchema),
        ]),
      ).annotate({ description: 'The Transaction associated with this object.' }),
    ),
  }).annotate({
    description:
      'You can reverse some [ReceivedCredits](https://docs.stripe.com/api#received_credits) depending on their network and source flow. Reversing a ReceivedCredit leads to the creation of a new object known as a CreditReversal.',
  })

export type TreasuryCreditReversal = Schema.Schema.Type<typeof TreasuryCreditReversalSchema>

type TreasuryTransactionType = {
  amount: number
  balance_impact: Schema.Schema.Type<typeof TreasuryTransactionsResourceBalanceImpactSchema>
  created: number
  currency: string
  description: string
  entries?: {
    data: readonly Schema.Schema.Type<typeof TreasuryTransactionEntrySchema>[]
    has_more: boolean
    object: 'list'
    url: string
  } | null
  financial_account: string
  flow?: string | null
  flow_details?: Schema.Schema.Type<typeof TreasuryTransactionsResourceFlowDetailsSchema>
  flow_type:
    | 'credit_reversal'
    | 'debit_reversal'
    | 'inbound_transfer'
    | 'issuing_authorization'
    | 'other'
    | 'outbound_payment'
    | 'outbound_transfer'
    | 'received_credit'
    | 'received_debit'
  id: string
  livemode: boolean
  object: 'treasury.transaction'
  status: 'open' | 'posted' | 'void'
  status_transitions: Schema.Schema.Type<
    typeof TreasuryTransactionsResourceAbstractTransactionResourceStatusTransitionsSchema
  >
}

export const TreasuryTransactionSchema: Schema.Codec<TreasuryTransactionType, unknown> =
  Schema.Struct({
    amount: Schema.Number.check(Schema.isInt()).annotate({
      description: 'Amount (in cents) transferred.',
    }),
    balance_impact: TreasuryTransactionsResourceBalanceImpactSchema,
    created: Schema.Number.check(Schema.isInt()).annotate({
      description:
        'Time at which the object was created. Measured in seconds since the Unix epoch.',
    }),
    currency: Schema.String.annotate({
      description:
        'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
    }),
    description: Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({
      description:
        'An arbitrary string attached to the object. Often useful for displaying to users.',
    }),
    entries: Schema.optionalKey(
      Schema.NullOr(
        Schema.Struct({
          data: Schema.Array(Schema.suspend(() => TreasuryTransactionEntrySchema)).annotate({
            description: 'Details about each object.',
          }),
          has_more: Schema.Boolean.annotate({
            description:
              'True if this list has another page of items after this one that can be fetched.',
          }),
          object: Schema.Literal('list').annotate({
            description:
              "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
          }),
          url: Schema.String.check(
            Schema.isPattern(/^\/v1\/treasury\/transaction_entries/),
            Schema.makeFilter((input) => [...input].length <= 5000, {
              expected: 'a string of at most 5000 characters',
            }),
          ).annotate({ description: 'The URL where this list can be accessed.' }),
        }),
      ).annotate({
        description:
          'A list of TransactionEntries that are part of this Transaction. This cannot be expanded in any list endpoints.',
      }),
    ),
    financial_account: Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: 'The FinancialAccount associated with this object.' }),
    flow: Schema.optionalKey(
      Schema.NullOr(
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
      ).annotate({ description: 'ID of the flow that created the Transaction.' }),
    ),
    flow_details: Schema.optionalKey(
      Schema.NullOr(
        Schema.Union([Schema.suspend(() => TreasuryTransactionsResourceFlowDetailsSchema)]),
      ).annotate({ description: 'Details of the flow that created the Transaction.' }),
    ),
    flow_type: Schema.Literals([
      'credit_reversal',
      'debit_reversal',
      'inbound_transfer',
      'issuing_authorization',
      'other',
      'outbound_payment',
      'outbound_transfer',
      'received_credit',
      'received_debit',
    ]).annotate({ description: 'Type of the flow that created the Transaction.' }),
    id: Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: 'Unique identifier for the object.' }),
    livemode: Schema.Boolean.annotate({
      description:
        'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
    }),
    object: Schema.Literal('treasury.transaction').annotate({
      description:
        "String representing the object's type. Objects of the same type share the same value.",
    }),
    status: Schema.Literals(['open', 'posted', 'void']).annotate({
      description: 'Status of the Transaction.',
    }),
    status_transitions:
      TreasuryTransactionsResourceAbstractTransactionResourceStatusTransitionsSchema,
  }).annotate({
    description:
      "Transactions represent changes to a [FinancialAccount's](https://docs.stripe.com/api#financial_accounts) balance.",
  })

export type TreasuryTransaction = Schema.Schema.Type<typeof TreasuryTransactionSchema>

