export const postV1ChargesChargeRefundHandler = defineHandler({
  param: Schema.toStandardSchemaV1(
    Schema.Struct({
      charge: Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    }),
  ),
  form: Schema.toStandardSchemaV1(
    Schema.StructWithRest(
      Schema.Struct({
        amount: Schema.optionalKey(
          Schema.String.check(Schema.isPattern(/^-?(?:0|[1-9]\d*)$/))
            .pipe(
              Schema.decodeTo(
                Schema.Finite,
                SchemaTransformation.transform({
                  decode: (input) => Number(input),
                  encode: (output) => String(output),
                }),
              ),
            )
            .check(Schema.isInt())
            .annotate({
              description:
                'A positive integer in the [smallest currency unit](https://docs.stripe.com/currencies#zero-decimal) representing how much of this charge to refund. Can refund only up to the remaining, unrefunded amount of the charge.',
            }),
        ),
        expand: Schema.optionalKey(
          Schema.Unknown.pipe(
            Schema.decodeTo(
              Schema.Unknown,
              SchemaTransformation.transform<unknown, unknown>({
                decode: (input) => (input === undefined || Array.isArray(input) ? input : [input]),
                encode: (output) => output,
              }),
            ),
            Schema.decodeTo(
              Schema.Array(
                Schema.String.check(
                  Schema.makeFilter((input) => [...input].length <= 5000, {
                    expected: 'a string of at most 5000 characters',
                  }),
                ),
              ),
            ),
          ).annotate({ description: 'Specifies which fields in the response should be expanded.' }),
        ),
        instructions_email: Schema.optionalKey(
          Schema.String.annotate({
            description:
              'For payment methods without native refund support (e.g., Konbini, PromptPay), use this email from the customer to receive refund instructions.',
          }),
        ),
        metadata: Schema.optionalKey(
          Schema.Union([Schema.Record(Schema.String, Schema.String), Schema.Literal('')]).annotate({
            description:
              'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
          }),
        ),
        payment_intent: Schema.optionalKey(
          Schema.String.check(
            Schema.makeFilter((input) => [...input].length <= 5000, {
              expected: 'a string of at most 5000 characters',
            }),
          ).annotate({ description: 'The identifier of the PaymentIntent to refund.' }),
        ),
        reason: Schema.optionalKey(
          Schema.Literals(['duplicate', 'fraudulent', 'requested_by_customer']).annotate({
            description:
              'String indicating the reason for the refund. If set, possible values are `duplicate`, `fraudulent`, and `requested_by_customer`. If you believe the charge to be fraudulent, specifying `fraudulent` as the reason will add the associated card and email to your [block lists](https://docs.stripe.com/radar/lists), and will also help us improve our fraud detection algorithms.',
          }),
        ),
        refund_application_fee: Schema.optionalKey(
          Schema.String.check(
            Schema.isPattern(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i),
          )
            .pipe(
              Schema.decodeTo(
                Schema.Boolean,
                SchemaTransformation.transform({
                  decode: (input) => /^(?:true|1|yes|on|y|enabled)$/i.test(input),
                  encode: (output) => (output ? 'true' : 'false'),
                }),
              ),
            )
            .annotate({
              description:
                'Boolean indicating whether the application fee should be refunded when refunding this charge. If a full charge refund is given, the full application fee will be refunded. Otherwise, the application fee will be refunded in an amount proportional to the amount of the charge refunded. An application fee can be refunded only by the application that created the charge.',
            }),
        ),
        reverse_transfer: Schema.optionalKey(
          Schema.String.check(
            Schema.isPattern(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i),
          )
            .pipe(
              Schema.decodeTo(
                Schema.Boolean,
                SchemaTransformation.transform({
                  decode: (input) => /^(?:true|1|yes|on|y|enabled)$/i.test(input),
                  encode: (output) => (output ? 'true' : 'false'),
                }),
              ),
            )
            .annotate({
              description:
                'Boolean indicating whether the transfer should be reversed when refunding this charge. The transfer will be reversed proportionally to the amount being refunded (either the entire or partial amount).<br><br>A transfer can be reversed only by the application that created the charge.',
            }),
        ),
      }),
      [Schema.Record(Schema.String, Schema.Unknown)],
    ).check(
      Schema.makeFilter((input) =>
        Object.keys(input).every((key) =>
          [
            'amount',
            'expand',
            'instructions_email',
            'metadata',
            'payment_intent',
            'reason',
            'refund_application_fee',
            'reverse_transfer',
          ].includes(key),
        ),
      ),
    ),
  ),
  response: Schema.toStandardSchemaV1(ChargeSchema),
})

