export const getV1IssuingCardsCardHandler = defineHandler({
  param: Schema.toStandardSchemaV1(
    Schema.Struct({
      card: Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    }),
  ),
  query: Schema.toStandardSchemaV1(
    Schema.Struct({
      expand: Schema.optionalKey(
        Schema.Unknown.pipe(
          Schema.decodeTo(
            Schema.Unknown,
            SchemaTransformation.transform<unknown, unknown>({
              decode: (input) => (input === undefined || Array.isArray(input) ? input : [input]),
              encode: (output) => output,
            }),
          ),
          Schema.decodeTo(
            Schema.Array(
              Schema.String.check(
                Schema.makeFilter((input) => [...input].length <= 5000, {
                  expected: 'a string of at most 5000 characters',
                }),
              ),
            ),
          ),
        ),
      ),
    }),
  ),
  form: Schema.toStandardSchemaV1(
    Schema.StructWithRest(Schema.Struct({}), [Schema.Record(Schema.String, Schema.Unknown)]).check(
      Schema.makeFilter((input) => Object.keys(input).length === 0),
    ),
  ),
  response: Schema.toStandardSchemaV1(IssuingCardSchema),
})

