export const postV1TestHelpersCustomersCustomerFundCashBalanceHandler = defineHandler({
  param: Schema.toStandardSchemaV1(
    Schema.Struct({
      customer: Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    }),
  ),
  form: Schema.toStandardSchemaV1(
    Schema.StructWithRest(
      Schema.Struct({
        amount: Schema.String.check(Schema.isPattern(/^-?(?:0|[1-9]\d*)$/))
          .pipe(
            Schema.decodeTo(
              Schema.Finite,
              SchemaTransformation.transform({
                decode: (input) => Number(input),
                encode: (output) => String(output),
              }),
            ),
          )
          .check(Schema.isInt())
          .annotate({
            description:
              'Amount to be used for this test cash balance transaction. A positive integer representing how much to fund in the [smallest currency unit](https://docs.stripe.com/currencies#zero-decimal) (e.g., 100 cents to fund $1.00 or 100 to fund ¥100, a zero-decimal currency).',
          }),
        currency: Schema.String.annotate({
          description:
            'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
        }),
        expand: Schema.optionalKey(
          Schema.Unknown.pipe(
            Schema.decodeTo(
              Schema.Unknown,
              SchemaTransformation.transform<unknown, unknown>({
                decode: (input) => (input === undefined || Array.isArray(input) ? input : [input]),
                encode: (output) => output,
              }),
            ),
            Schema.decodeTo(
              Schema.Array(
                Schema.String.check(
                  Schema.makeFilter((input) => [...input].length <= 5000, {
                    expected: 'a string of at most 5000 characters',
                  }),
                ),
              ),
            ),
          ).annotate({ description: 'Specifies which fields in the response should be expanded.' }),
        ),
        reference: Schema.optionalKey(
          Schema.String.check(
            Schema.makeFilter((input) => [...input].length <= 5000, {
              expected: 'a string of at most 5000 characters',
            }),
          ).annotate({
            description:
              "A description of the test funding. This simulates free-text references supplied by customers when making bank transfers to their cash balance. You can use this to test how Stripe's [reconciliation algorithm](https://docs.stripe.com/payments/customer-balance/reconciliation) applies to different user inputs.",
          }),
        ),
      }),
      [Schema.Record(Schema.String, Schema.Unknown)],
    ).check(
      Schema.makeFilter((input) =>
        Object.keys(input).every((key) =>
          ['amount', 'currency', 'expand', 'reference'].includes(key),
        ),
      ),
    ),
  ),
  response: Schema.toStandardSchemaV1(CustomerCashBalanceTransactionSchema),
})

